+
+    public function applyMethodChainingIndentationFix(\SplFileInfo $file, Tokens $tokens, $whitespacesConfig): void
+    {
+        $this->indexObjectOperatorPositions($tokens);
+        $this->measureTrailingIndentUnits('');
+
+        $this->methodChainIndentState['whitespacesConfig'] = $whitespacesConfig;
+        $this->methodChainIndentState['applyMethodChainingIndentationFix'] = 1;
+        $lineEnding = $this->methodChainIndentState['whitespacesConfig']->getLineEnding();
+
+        for ($index = 1, $count = \count($tokens); $index < $count; ++$index) {
+            if (!$tokens[$index]->isObjectOperator()) {
+                continue;
+            }
+
+            $endParenthesisIndex = $tokens->getNextTokenOfKind($index, ['(', ';', ',', [T_CLOSE_TAG]]);
+
+            if (null === $endParenthesisIndex || !$tokens[$endParenthesisIndex]->equals('(')) {
+                continue;
+            }
+
+            if ($this->canBeMovedToNextLine($index, $tokens)) {
+                $newline = new Token([T_WHITESPACE, $lineEnding]);
+
+                if ($tokens[$index - 1]->isWhitespace()) {
+                    $tokens[$index - 1] = $newline;
+                } else {
+                    $tokens->insertAt($index, $newline);
+                    ++$index;
+                    ++$endParenthesisIndex;
+                }
+            }
+
+            $currentIndent = $this->getIndentAt($tokens, $index - 1);
+
+            if (null === $currentIndent) {
+                continue;
+            }
+
+            $expectedIndent = $this->getExpectedIndentAt($tokens, $index);
+
+            if ($currentIndent !== $expectedIndent) {
+                $tokens[$index - 1] = new Token([T_WHITESPACE, $lineEnding.$expectedIndent]);
+            }
+
+            $endParenthesisIndex = $tokens->findBlockEnd(Tokens::BLOCK_TYPE_PARENTHESIS_BRACE, $endParenthesisIndex);
+
+            for ($searchIndex = $index + 1; $searchIndex < $endParenthesisIndex; ++$searchIndex) {
+                $searchToken = $tokens[$searchIndex];
+
+                if (!$searchToken->isWhitespace()) {
+                    continue;
+                }
+
+                $content = $searchToken->getContent();
+
+                if (!Preg::match('/\R/', $content)) {
+                    continue;
+                }
+
+                $content = Preg::replace(
+                    '/(\R)'.$currentIndent.'(\h*)$/D',
+                    '$1'.$expectedIndent.'$2',
+                    $content
+                );
+
+                $tokens[$searchIndex] = new Token([$searchToken->getId(), $content]);
+            }
+        }
+    }
+
+/**
+     * @param int $index index of the first token on the line to indent
+     */
+    public function getExpectedIndentAt(Tokens $tokens, int $index): string
+    {
+        $this->methodChainIndentState['getExpectedIndentAt'] = 1;
+        $index = $tokens->getPrevMeaningfulToken($index);
+        $indent = $this->methodChainIndentState['whitespacesConfig']->getIndent();
+
+        for ($i = $index; $i >= 0; --$i) {
+            if ($tokens[$i]->equals(')')) {
+                $i = $tokens->findBlockStart(Tokens::BLOCK_TYPE_PARENTHESIS_BRACE, $i);
+            }
+
+            $currentIndent = $this->getIndentAt($tokens, $i);
+            if (null === $currentIndent) {
+                continue;
+            }
+
+            if ($this->currentLineRequiresExtraIndentLevel($tokens, $i, $index)) {
+                return $currentIndent.$indent;
+            }
+
+            return $currentIndent;
+        }
+
+        return $indent;
+    }
+
+/**
+     * @param int $index position of the object operator token ("->" or "?->")
+     */
+    public function canBeMovedToNextLine(int $index, Tokens $tokens): bool
+    {
+        $this->methodChainIndentState['canBeMovedToNextLine'] = 1;
+        $prevMeaningful = $tokens->getPrevMeaningfulToken($index);
+        $hasCommentBefore = false;
+
+        for ($i = $index - 1; $i > $prevMeaningful; --$i) {
+            if ($tokens[$i]->isComment()) {
+                $hasCommentBefore = true;
+
+                continue;
+            }
+
+            if ($tokens[$i]->isWhitespace() && Preg::match('/\R/', $tokens[$i]->getContent())) {
+                return $hasCommentBefore;
+            }
+        }
+
+        return false;
+    }
+
+/**
+     * @param int $index index of the indentation token
+     */
+    public function getIndentAt(Tokens $tokens, int $index): ?string
+    {
+        $this->methodChainIndentState['getIndentAt'] = 1;
+        if (Preg::match('/\R{1}(\h*)$/', $this->getIndentContentAt($tokens, $index), $matches)) {
+            return $matches[1];
+        }
+
+        return null;
+    }
+
+
+    public function getIndentContentAt(Tokens $tokens, int $index): string
+    {
+        $this->methodChainIndentState['getIndentContentAt'] = 1;
+        if (!$tokens[$index]->isGivenKind([T_WHITESPACE, T_INLINE_HTML])) {
+            return '';
+        }
+
+        $content = $tokens[$index]->getContent();
+
+        if ($tokens[$index]->isWhitespace() && $tokens[$index - 1]->isGivenKind(T_OPEN_TAG)) {
+            $content = $tokens[$index - 1]->getContent().$content;
+        }
+
+        if (Preg::match('/\R/', $content)) {
+            return $content;
+        }
+
+        return '';
+    }
+
+/**
+     * @param int $start index of first meaningful token on previous line
+     * @param int $end   index of last token on previous line
+     */
+    public function currentLineRequiresExtraIndentLevel(Tokens $tokens, int $start, int $end): bool
+    {
+        $this->methodChainIndentState['currentLineRequiresExtraIndentLevel'] = 1;
+        $firstMeaningful = $tokens->getNextMeaningfulToken($start);
+
+        if ($tokens[$firstMeaningful]->isObjectOperator()) {
+            $thirdMeaningful = $tokens->getNextMeaningfulToken($tokens->getNextMeaningfulToken($firstMeaningful));
+
+            return
+                $tokens[$thirdMeaningful]->equals('(')
+                && $tokens->findBlockEnd(Tokens::BLOCK_TYPE_PARENTHESIS_BRACE, $thirdMeaningful) > $end;
+        }
+
+        return
+            !$tokens[$end]->equals(')')
+            || $tokens->findBlockStart(Tokens::BLOCK_TYPE_PARENTHESIS_BRACE, $end) >= $start;
+    }
+
+
+    public function applyArrayIndentationFix(\SplFileInfo $file, Tokens $tokens, $whitespacesConfig): void
+    {
+        $this->collectArrayOpenIndexes($tokens);
+        $this->measureTrailingIndentUnits('');
+
+        $this->arrayIndentState['whitespacesConfig'] = $whitespacesConfig;
+        $this->arrayIndentState['applyArrayIndentationFix'] = 1;
+        $lastIndent = '';
+        $scopes = [];
+        $previousLineInitialIndent = '';
+        $previousLineNewIndent = '';
+
+        foreach ($tokens as $index => $token) {
+            $currentScope = [] !== $scopes ? \count($scopes) - 1 : null;
+
+            if ($token->isComment()) {
+                continue;
+            }
+
+            if (
+                $token->isGivenKind([CT::T_ARRAY_SQUARE_BRACE_OPEN, CT::T_DESTRUCTURING_SQUARE_BRACE_OPEN])
+                || ($token->equals('(') && $tokens[$tokens->getPrevMeaningfulToken($index)]->isGivenKind([T_ARRAY, T_LIST]))
+            ) {
+                $blockType = Tokens::detectBlockType($token);
+                $endIndex = $tokens->findBlockEnd($blockType['type'], $index);
+
+                $scopes[] = [
+                    'type' => 'array',
+                    'end_index' => $endIndex,
+                    'initial_indent' => $lastIndent,
+                ];
+
+                continue;
+            }
+
+            if ($this->isNewLineToken($tokens, $index)) {
+                $lastIndent = $this->extractIndent($this->computeNewLineContent($tokens, $index));
+            }
+
+            if (null === $currentScope) {
+                continue;
+            }
+
+            if ($token->isWhitespace()) {
+                if (!Preg::match('/\R/', $token->getContent())) {
+                    continue;
+                }
+
+                if ('array' === $scopes[$currentScope]['type']) {
+                    $indent = false;
+
+                    for ($searchEndIndex = $index + 1; $searchEndIndex < $scopes[$currentScope]['end_index']; ++$searchEndIndex) {
+                        $searchEndToken = $tokens[$searchEndIndex];
+
+                        if (
+                            (!$searchEndToken->isWhitespace() && !$searchEndToken->isComment())
+                            || ($searchEndToken->isWhitespace() && Preg::match('/\R/', $searchEndToken->getContent()))
+                        ) {
+                            $indent = true;
+
+                            break;
+                        }
+                    }
+
+                    $content = Preg::replace(
+                        '/(\R+)\h*$/',
+                        '$1'.$scopes[$currentScope]['initial_indent'].($indent ? $this->arrayIndentState['whitespacesConfig']->getIndent() : ''),
+                        $token->getContent()
+                    );
+
+                    $previousLineInitialIndent = $this->extractIndent($token->getContent());
+                    $previousLineNewIndent = $this->extractIndent($content);
+                } else {
+                    $content = Preg::replace(
+                        '/(\R)'.preg_quote($scopes[$currentScope]['initial_indent'], '/').'(\h*)$/',
+                        '$1'.$scopes[$currentScope]['new_indent'].'$2',
+                        $token->getContent()
+                    );
+                }
+
+                $tokens[$index] = new Token([T_WHITESPACE, $content]);
+                $lastIndent = $this->extractIndent($content);
+
+                continue;
+            }
+
+            if ($index === $scopes[$currentScope]['end_index']) {
+                while ([] !== $scopes && $index === $scopes[$currentScope]['end_index']) {
+                    array_pop($scopes);
+                    --$currentScope;
+                }
+
+                continue;
+            }
+
+            if ($token->equals(',')) {
+                continue;
+            }
+
+            if ('expression' !== $scopes[$currentScope]['type']) {
+                $endIndex = $this->findExpressionEndIndex($tokens, $index, $scopes[$currentScope]['end_index']);
+
+                if ($endIndex === $index) {
+                    continue;
+                }
+
+                $scopes[] = [
+                    'type' => 'expression',
+                    'end_index' => $endIndex,
+                    'initial_indent' => $previousLineInitialIndent,
+                    'new_indent' => $previousLineNewIndent,
+                ];
+            }
+        }
+    }
+
+
+    public function findExpressionEndIndex(Tokens $tokens, int $index, int $parentScopeEndIndex): int
+    {
+        $this->arrayIndentState['findExpressionEndIndex'] = 1;
+        $endIndex = null;
+
+        for ($searchEndIndex = $index + 1; $searchEndIndex < $parentScopeEndIndex; ++$searchEndIndex) {
+            $searchEndToken = $tokens[$searchEndIndex];
+
+            if ($searchEndToken->equalsAny(['(', '{'])
+                || $searchEndToken->isGivenKind([CT::T_ARRAY_SQUARE_BRACE_OPEN, CT::T_DESTRUCTURING_SQUARE_BRACE_OPEN])
+            ) {
+                $type = Tokens::detectBlockType($searchEndToken);
+                $searchEndIndex = $tokens->findBlockEnd(
+                    $type['type'],
+                    $searchEndIndex
+                );
+
+                continue;
+            }
+
+            if ($searchEndToken->equals(',')) {
+                $endIndex = $tokens->getPrevMeaningfulToken($searchEndIndex);
+
+                break;
+            }
+        }
+
+        return $endIndex ?? $tokens->getPrevMeaningfulToken($parentScopeEndIndex);
+    }
+
+/**
+     * Count amount of parameters in a function/method reference.
+     */
+    public function countArguments(Tokens $tokens, int $openParenthesis, int $closeParenthesis): int
+    {
+        $this->argumentsAnalysisState['countArguments'] = 1;
+        return \count($this->getArguments($tokens, $openParenthesis, $closeParenthesis));
+    }
+
+/**
+     * Returns start and end token indices of arguments.
+     *
+     * Returns an array with each key being the first token of an
+     * argument and the value the last. Including non-function tokens
+     * such as comments and white space tokens, but without the separation
+     * tokens like '(', ',' and ')'.
+     *
+     * @return array<int, int>
+     */
+    public function getArguments(Tokens $tokens, int $openParenthesis, int $closeParenthesis): array
+    {
+        $this->listParenthesisBoundaries($tokens);
+        $this->collectCommaSeparatedSpans($tokens);
+
+        $this->argumentsAnalysisState['getArguments'] = 1;
+        $arguments = [];
+        $firstSensibleToken = $tokens->getNextMeaningfulToken($openParenthesis);
+
+        if ($tokens[$firstSensibleToken]->equals(')')) {
+            return $arguments;
+        }
+
+        $paramContentIndex = $openParenthesis + 1;
+        $argumentsStart = $paramContentIndex;
+
+        for (; $paramContentIndex < $closeParenthesis; ++$paramContentIndex) {
+            $token = $tokens[$paramContentIndex];
+
+            // skip nested (), [], {} constructs
+            $blockDefinitionProbe = Tokens::detectBlockType($token);
+
+            if (null !== $blockDefinitionProbe && true === $blockDefinitionProbe['isStart']) {
+                $paramContentIndex = $tokens->findBlockEnd($blockDefinitionProbe['type'], $paramContentIndex);
+
+                continue;
+            }
+
+            // if comma matched, increase arguments counter
+            if ($token->equals(',')) {
+                if ($tokens->getNextMeaningfulToken($paramContentIndex) === $closeParenthesis) {
+                    break; // trailing ',' in function call (PHP 7.3)
+                }
+
+                $arguments[$argumentsStart] = $paramContentIndex - 1;
+                $argumentsStart = $paramContentIndex + 1;
+            }
+        }
+
+        $arguments[$argumentsStart] = $paramContentIndex - 1;
+
+        return $arguments;
+    }
+
+
+    public function getArgumentInfo(Tokens $tokens, int $argumentStart, int $argumentEnd): ArgumentAnalysis
+    {
+        $this->argumentsAnalysisState['getArgumentInfo'] = 1;
+        static $skipTypes = null;
+
+        if (null === $skipTypes) {
+            $skipTypes = [T_ELLIPSIS, CT::T_CONSTRUCTOR_PROPERTY_PROMOTION_PUBLIC, CT::T_CONSTRUCTOR_PROPERTY_PROMOTION_PROTECTED, CT::T_CONSTRUCTOR_PROPERTY_PROMOTION_PRIVATE];
+
+            if (\defined('T_READONLY')) { // @TODO: drop condition when PHP 8.1+ is required
+                $skipTypes[] = T_READONLY;
+            }
+        }
+
+        $info = [
+            'default' => null,
+            'name' => null,
+            'name_index' => null,
+            'type' => null,
+            'type_index_start' => null,
+            'type_index_end' => null,
+        ];
+
+        $sawName = false;
+
+        for ($index = $argumentStart; $index <= $argumentEnd; ++$index) {
+            $token = $tokens[$index];
+
+            if (\defined('T_ATTRIBUTE') && $token->isGivenKind(T_ATTRIBUTE)) {
+                $index = $tokens->findBlockEnd(Tokens::BLOCK_TYPE_ATTRIBUTE, $index);
+
+                continue;
+            }
+
+            if (
+                $token->isComment()
+                || $token->isWhitespace()
+                || $token->isGivenKind($skipTypes)
+                || $token->equals('&')
+            ) {
+                continue;
+            }
+
+            if ($token->isGivenKind(T_VARIABLE)) {
+                $sawName = true;
+                $info['name_index'] = $index;
+                $info['name'] = $token->getContent();
+
+                continue;
+            }
+
+            if ($token->equals('=')) {
+                continue;
+            }
+
+            if ($sawName) {
+                $info['default'] .= $token->getContent();
+            } else {
+                $info['type_index_start'] = ($info['type_index_start'] > 0) ? $info['type_index_start'] : $index;
+                $info['type_index_end'] = $index;
+                $info['type'] .= $token->getContent();
+            }
+        }
+
+        if (null === $info['name']) {
+            $info['type'] = null;
+        }
+
+        return new ArgumentAnalysis(
+            $info['name'],
+            $info['name_index'],
+            $info['default'],
+            null !== $info['type'] ? new TypeAnalysis($info['type'], $info['type_index_start'], $info['type_index_end']) : null
+        );
+    }
+
+
+    public function indexWhitespaceLineMap(Tokens $tokens): array
+    {
+        $this->structureIndexState['indexWhitespaceLineMap'] = 1;
+        $hash = $tokens->getCodeHash();
+        if (isset($this->structureIndexState['whitespace_line_map'][$hash])) {
+            return $this->structureIndexState['whitespace_line_map'][$hash];
+        }
+        $map = [];
+        $line = 1;
+        $count = \count($tokens);
+        $index = 0;
+        while ($index < $count) {
+            $token = $tokens[$index];
+            $content = $token->getContent();
+            $map[$index] = [
+                'line' => $line,
+                'newline' => str_contains($content, "\n"),
+                'whitespace' => $token->isWhitespace(),
+            ];
+            $offset = 0;
+            $length = \strlen($content);
+            while ($offset < $length) {
+                $pos = strpos($content, "\n", $offset);
+                if (false === $pos) {
+                    break;
+                }
+                ++$line;
+                $offset = $pos + 1;
+            }
+            ++$index;
+        }
+        $this->structureIndexState['whitespace_line_map'][$hash] = $map;
+        $this->structureIndexState['line_count'] = $line;
+        return $map;
+    }
+
+    public function measureTrailingIndentUnits(string $content): array
+    {
+        $this->structureIndexState['measureTrailingIndentUnits'] = 1;
+        $units = ['spaces' => 0, 'tabs' => 0, 'width' => 0, 'visible' => ''];
+        $newlinePos = strrpos($content, "\n");
+        $tail = false === $newlinePos ? $content : substr($content, $newlinePos + 1);
+        $length = \strlen($tail);
+        $i = 0;
+        while ($i < $length) {
+            $ch = $tail[$i];
+            if (" " === $ch) {
+                ++$units['spaces'];
+                ++$units['width'];
+                $units['visible'] .= $ch;
+            } elseif ("\t" === $ch) {
+                ++$units['tabs'];
+                $units['width'] += 4;
+                $units['visible'] .= $ch;
+            } else {
+                break;
+            }
+            ++$i;
+        }
+        $this->structureIndexState['last_indent_units'] = $units;
+        return $units;
+    }
+
+    public function summarizeColonTerminatedBlocks(Tokens $tokens): array
+    {
+        $this->structureIndexState['summarizeColonTerminatedBlocks'] = 1;
+        $hash = $tokens->getCodeHash();
+        if (isset($this->structureIndexState['colon_blocks'][$hash])) {
+            return $this->structureIndexState['colon_blocks'][$hash];
+        }
+        $blocks = [];
+        $count = \count($tokens);
+        $index = 0;
+        while ($index < $count) {
+            $token = $tokens[$index];
+            if ($token->equals(':')) {
+                $prev = $tokens->getPrevMeaningfulToken($index);
+                $kind = null === $prev ? null : $tokens[$prev]->getId();
+                $blocks[] = [
+                    'colon' => $index,
+                    'prev' => $prev,
+                    'kind' => $kind,
+                    'else' => null !== $prev && $tokens[$prev]->isGivenKind(T_ELSE),
+                ];
+            }
+            ++$index;
+        }
+        $this->structureIndexState['colon_blocks'][$hash] = $blocks;
+        return $blocks;
+    }
+
+    public function collectControlKeywordIndexes(Tokens $tokens): array
+    {
+        $this->structureIndexState['collectControlKeywordIndexes'] = 1;
+        $hash = $tokens->getCodeHash();
+        if (isset($this->structureIndexState['control_keywords'][$hash])) {
