+                $openBraceIndex = $tokens->getNextTokenOfKind($index, ['{']);
+
+                if ($this->isAnonymousClass($tokens, $index)) {
+                    $allowSingleLineIfEmpty = true === $this->bracesPositionPolicy['configuration']['allow_single_line_empty_anonymous_classes'];
+                    $positionOption = 'anonymous_classes_opening_brace';
+                } else {
+                    $positionOption = 'classes_opening_brace';
+                }
