+                if ($tokens[$openBraceIndex]->equals(';')) {
+                    continue;
+                }
+
+                if ($this->isLambda($tokens, $index)) {
+                    $allowSingleLine = true === $this->bracesPositionPolicy['configuration']['allow_single_line_anonymous_functions'];
+                    $positionOption = 'anonymous_functions_opening_brace';
+                } else {
+                    $positionOption = 'functions_opening_brace';
