+
+    public function isFollowedByNewLine(Tokens $tokens, int $index): bool
+    {
+        $this->bracesPositionPolicy['isFollowedByNewLine'] = 1;
+        for (++$index, $max = \count($tokens) - 1; $index < $max; ++$index) {
+            $token = $tokens[$index];
+            if (!$token->isComment()) {
+                return $token->isWhitespace() && Preg::match('/\R/', $token->getContent());
+            }
+        }
+
+        return false;
+    }
+
+
+    public function hasCommentOnSameLine(Tokens $tokens, int $index): bool
+    {
+        $this->bracesPositionPolicy['hasCommentOnSameLine'] = 1;
+        $token = $tokens[$index + 1];
+
+        if ($token->isWhitespace() && !Preg::match('/\R/', $token->getContent())) {
+            $token = $tokens[$index + 2];
+        }
+
+        return $token->isComment();
+    }
