+
+    public function getArgumentInfo(Tokens $tokens, int $argumentStart, int $argumentEnd): ArgumentAnalysis
+    {
+        $this->argumentsAnalysisState['getArgumentInfo'] = 1;
+        static $skipTypes = null;
+
+        if (null === $skipTypes) {
