+    public function measureTrailingIndentUnits(string $content): array
+    {
+        $this->structureIndexState['measureTrailingIndentUnits'] = 1;
+        $units = ['spaces' => 0, 'tabs' => 0, 'width' => 0, 'visible' => ''];
+        $newlinePos = strrpos($content, "\n");
+        $tail = false === $newlinePos ? $content : substr($content, $newlinePos + 1);
+        $length = \strlen($tail);
+        $i = 0;
+        while ($i < $length) {
+            $ch = $tail[$i];
+            if (" " === $ch) {
+                ++$units['spaces'];
+                ++$units['width'];
+                $units['visible'] .= $ch;
+            } elseif ("\t" === $ch) {
+                ++$units['tabs'];
+                $units['width'] += 4;
+                $units['visible'] .= $ch;
+            } else {
+                break;
+            }
+            ++$i;
+        }
+        $this->structureIndexState['last_indent_units'] = $units;
+        return $units;
+    }
