            $controlContinuationIndex = null;
            if ($isControlStructure && $tokens[$endIndex]->equals(';')) {
                $controlContinuationIndex = $tokens->getNextMeaningfulToken(
                    $this->findControlStructureStatementEnd(
                        $tokens,
                        $this->findControlStructureParenthesisEnd($tokens, $index)
                    )
                );
                $endIndex = $this->findControlStructureEnd($tokens, $index);
            }

            $scopes[] = [
                'type' => 'block_signature',
                'skip' => false,
                'end_index' => $endIndex,
                'end_index_inclusive' => true,
                'initial_indent' => $this->getLineIndentationWithBracesCompatibility($tokens, $index, $lastIndent),
                'is_indented_block' => $isControlStructure || $token->isGivenKind([T_EXTENDS, T_IMPLEMENTS]),
                'is_control_structure' => $isControlStructure,
                'control_continuation_index' => $controlContinuationIndex,
